import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = 0
    for x in op:
        if x == 'C':
            op_c += 1
    op_d = n - op_c

    my_last = my[-1]
    op_last = op[-1]

    # If opponent has almost never defected, cooperate but probe rarely.
    if op_d == 0:
        if n == 50:
            return 'D'
        return 'C'
    if op_d <= n // 20:
        if n % 25 == 0:
            return 'D'
        return 'C'

    # Last-10 stats
    start = n - 10
    if start < 0:
        start = 0
    recent_op_d = 0
    recent_my_d = 0
    for i in range(start, n):
        if op[i] == 'D':
            recent_op_d += 1
        if my[i] == 'D':
            recent_my_d += 1
    recent_len = n - start

    # Opponent heavily defecting recently: punish
    if recent_op_d * 2 > recent_len:
        if op_last == 'D':
            if my_last == 'D':
                if recent_op_d >= 7:
                    return 'D'
                if rng.random() < 0.2:
                    return 'C'
                return 'D'
            return 'D'
        if my_last == 'D':
            if rng.random() < 0.15:
                return 'D'
            return 'C'
        return 'C'

    # Opponent mostly cooperative recently
    if recent_op_d == 0:
        if recent_my_d >= 5:
            return 'C'
        if n > 10 and n % 19 == 0:
            return 'D'
        return 'C'

    # If opponent just defected
    if op_last == 'D':
        if my_last == 'D':
            if recent_op_d >= 4 or recent_my_d >= 4:
                if rng.random() < 0.12:
                    return 'C'
                return 'D'
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        else:
            if recent_op_d >= 3:
                return 'D'
            if rng.random() < 0.1:
                return 'C'
            return 'D'

    # Opponent just cooperated
    if my_last == 'D':
        # return to cooperation most of the time
        if recent_my_d >= 3 and recent_op_d <= 1:
            if rng.random() < 0.2:
                return 'D'
        return 'C'

    # Both cooperating: stay cooperative, mild exploitation pressure
    if op_d * 4 < n:
        if n > 40 and n % 23 == 0 and op_last == 'C':
            return 'D'
        return 'C'

    if recent_my_d == 0 and recent_op_d == 1:
        if rng.random() < 0.15:
            return 'D'
        return 'C'

    if op_last == 'C':
        return 'C'
    return 'D'
